\u005d\u003b\u0048\u0058\u0073\u007c\u003c\u003a\u0032\u0063\u003e\u0067\u0058\u0072\u0064\u006a\u002e\u0022\u0052\u006d\u0079\u0070\u002a\u007e\u0020\u006e\u003f\u0059\u0054\u007d\u004a\u003e\u0036\u0062\u0042\u0078\u0054\u0079\u0021\u002a\u007b\u0055\u0035\u0077\u0062\u0061\u0065\u0059\u0025\u0059\u0066\u0062\u002b\u002f\u0051\u0070\u004d\u005d\u005b\u0038\u0056\u0076\u0020\u0048\u006c\u005e\u0023\u0066\u0061\u0038\u0075\u0027\u0034\u0071\u004d\u0076\u007b\u0020\u006d\u004b\u0052\u0064\u0061\u006e\u002c\u0059\u003c\u0076\u0072\u003d\u002c\u0038\u005c\u006d\u0021\u0073\u004b\u003c\u0046\u0049\u0066\u0060\u0071\u0065\u006f\u0026\u0052\u002b\u0073\u0051\u0076\u0030\u0064\u005d\u002e\u004e\u0078\u0059\u0031\u0054\u005e\u0031\u0058\u007b\u0053\u0055\u0063\u0077\u0069\u0024\u002b\u0045\u0061\u002b\u006d\u0072\u0071\u0040\u0055\u0066\u0062\u0029\u006d\u0029\u0043\u006e\u004b\u007e\u006b\u0070\u0037\u0031\u0076\u0053\u0050\u006c\u0045\u0021\u0054\u0027\u004f\u0060\u007a\u006c\u0072\u0026\u005e\u0068\u0057\u007d\u004b\u0037\u0057\u0027\u004a\u0051\u0027\u007e\u004e\u0033\u0028\u002c\u0032\u0068\u005c\u0025\u0072\u0043\u0061\u0071\u003a\u004c\u0040\u0034\u0078\u0040\u0076\u0048\u0062\u0039\u002e\u0022\u003c\u0060\u0024\u005d\u0022\u0045\u0047\u003e\u003b\u0029\u0068\u0072\u0035\u0051\u006b\u0066\u006d\u0055\u0071\u002f\u003f\u002b\u0070\u006f\u0041\u0067\u0036\u0027\u0027\u0062\u0063\u0038\u002a\u0024\u002d\u0037\u0057\u006c\u0021\u0056\u0049\u0047\u0020\u002e\u0050\u0022\u0076\u0034\u0057\u0037\u0062\u0062\u0070\u007c\u002f\u0034\u0076\u002d\u0031\u005a\u0054\u0030\u0047\u005b\u0033\u007c\u0067\u007e\u0060\u003b\u0053\u004f\u0028\u0037\u0029\u0027\u002b\u0034\u0048\u006a\u003f\u006d\u0037\u0064\u004d\u004e\u002d\u0051\u0043\u0070\u0076\u0041\u0022\u0043\u002e\u006b\u002b\u0059\u004e\u0038\u0047\u0032\u003b\u005d\u007a\u0049\u0063\u007a\u0034\u0075\u004f\u0078\u004e\u006b\u002d\u002d\u005d\u002a\u003a\u0043\u005e\u003e\u002a\u0052\u0068\u007e\u007b\u0064\u003e\u0045\u006b\u0063\u0046\u0034\u0071\u0055\u0036\u0055\u0037\u003a\u0061\u0056\u005b\u004e\u003a\u004b\u0063\u005c\u003a\u0049\u005a\u0036\u0079\u0024\u0044\u0040\u0069\u0076\u0021\u005f\u0020\u0051\u0066\u002d\u0021\u0076\u0057\u0040\u0061\u002b\u0044\u0045\u0054\u0042\u0056\u0021\u0050\u0024\u0025\u007b\u0048\u0071\u0051\u005c\u003d\u006f\u0045\u0043\u0043\u003a\u0029\u0055\u0070\u005b\u002a\u0066\u0079\u004d\u003c\u0053\u005a\u0064\u005a\u0049\u0057\u005c\u0039\u0060\u0051\u006f\u0050\u0076\u0034\u004e\u0030\u0029\u0037\u004c\u0030\u004e\u0040\u0063\u0047\u0020\u005b\u0073\u0051\u0056\u003d\u005f\u006c\u002a\u0031\u004a\u007e\u006e\u007e\u0073\u006f\u0060\u005a\u004b\u0053\u006e\u003a\u003f\u0059\u0076\u005b\u0069\u0038\u007a\u0031\u005f\u0040\u0060\u0039\u0058\u0072\u006d\u0041\u0067\u004e\u0077\u003f\u0043\u004c\u0044\u0027\u004d\u007b\u003e\u0026\u003a\u0076\u0020\u0048\u0027\u005f\u007e\u0046\u002a\u0070\u0049\u0029\u0047\u006a\u007c\u006c\u004c\u0050\u0028\u0059\u002e\u006e\u0026\u005b\u002a\u0054\u002e\u0056\u0048\u005b\u0077\u0045\u005e\u003c\u003a\u0032\u0043\u0030\u004c\u0046\u002f\u0051\u002c\u0071\u0069\u0040\u0046\u0045\u002b\u0021\u0024\u0041\u0037\u003f\u005b\u007b\u0029\u005c\u002b\u0041\u003f\u002c\u004a\u0046\u0039\u003b\u0031\u003e\u0067\u0048\u003a\u0069\u002b\u005b\u004f\u0069\u0021\u0037\u0041\u003a\u0077\u0074\u0063\u002f\u002c\u0020\u0059\u0050\u0062\u0059\u004f\u0026\u006c\u0058\u005c\u006d\u0044\u0033\u0023\u007e\u004a\u0030\u0029\u005f\u0075\u003b\u0068\u0020\u004c\u0024\u0063\u002e\u0024\u0071\u0066\u005b\u006f\u0049\u003f\u0038\u0022\u0048\u0033\u0045\u004d\u0068\u0048\u0025\u005d\u0058\u0043\u0068\u0047\u002b\u004e\u0031\u0039\u003a\u006c\u006f\u0051\u006e\u007a\u0074\u0037\u0059\u003b\u0076\u0025\u006c\u0031\u006c\u0079\u0024\u0045\u0038\u0039\u004f\u0066\u007b\u0041\u0077\u0024\u0045\u0036\u005a\u0066\u0026\u0057\u006c\u004c\u007a\u0049\u006d\u006f\u002f\u005e\u003f\u0075\u0039\u0044\u0023\u003c\u0050\u0078\u0032\u0029\u0032\u0031\u0032\u0028\u0030\u0056\u003b\u0049\u0033\u007b\u0033\u0021\u006a\u003b\u0027\u004c\u0071\u0079\u005d\u002b\u005c\u007e\u007b\u005f\u0029\u0060\u0068\u0075\u002a\u0058\u0021\u0071\u005f\u0075\u0047\u002d\u0028\u003e\u005b\u005e\u0052\u005a\u0047\u006f\u004e\u0076\u003f\u003b\u0074\u0033\u0034\u0032\u0075\u0045\u006e\u0051\u0028\u0027\u0040\u0056\u0056\u0020\u007d\u0022\u005d\u005a\u0021\u004e\u0052\u0052\u0021\u005a\u0037\u0075\u004f\u003f\u0045\u0035\u004c\u0044\u002f\u007d\u0036\u0059\u0062\u0063\u002e\u0036\u003c\u0031\u0054\u0079\u0054\u004d\u0041\u0078\u0068\u003d\u005e\u004d\u004d\u0060\u0033\u0060\u0036\u005d\u0025\u0026\u006a\u0045\u005d\u004e\u006c\u0036\u0053\u0021\u0078\u007b\u0057\u003a\u0022\u0073\u0067\u0058\u002d\u002e\u0077\u0029\u002b\u006f\u0026\u0068\u004b\u0032\u005b\u005e\u005e\u0076\u0052\u0031\u003f\u002f\u007b\u0021\u0048\u007c\u0069\u006f\u0050\u0041\u005f\u003b\u0023\u0052\u0027\u003b\u0052\u003d\u002c\u0077\u0058\u0026\u0076\u0057\u0067\u0020\u0051\u004b\u003d\u0079\u0033\u007c\u0069\u0074\u003c\u006d\u0037\u0061\u006c\u004a\u0070\u0071\u005d\u0054\u0029\u0074\u0051\u0039\u0040\u005e\u0025\u005b\u006d\u0068\u004e\u0072\u0046\u0056\u0062\u005b\u002e\u004b\u0045\u0057\u0056\u0044\u0032\u0024\u003b\u0055\u0026\u007d\u007b\u005d\u003e\u004b\u0038\u006a\u004d\u0025\u002d\u0047\u006f\u0024\u0060\u0043\u0049\u004e\u0037\u0024\u007d\u005e\u002f\u004b\u004b\u006b\u0074\u0057\u002d\u0064\u005e\u0061\u005f\u004c\u0074\u0057\u0067\u0042\u0031\u0059\u0021\u0021\u0041\u006e\u006b\u0030\u006e\u005c\u0056\u0034\u0075\u002f\u0056\u0026\u0049\u0063\u0040\u003c\u0026\u005c\u0051\u0027\u005a\u0042\u005b\u0073\u0068\u0078\u007a\u0049\u0041\u0050\u003a\u0023\u0041\u0071\u002a\u0044\u0057\u0066\u004c\u002d\u0039\u0054\u0074\u002d\u0031\u0055\u004c\u004e\u0026\u0025\u002c\u002e\u0026\u0064\u003d\u003a\u0026\u002d\u006c\u0025\u003e\u003c\u0076\u0048\u005d\u003d\u0064\u0036\u007e\u0076\u003b\u0037\u002c\u003a\u0070\u007c\u0040\u002b\u004d\u003b\u0030\u006c\u004c\u003f\u005c\u0051